INSERT INTO `event` (`id`, `name`, `image`, `company_logo`, `start_date`, `end_date`, `shift_start_time`, `shift_end_time`, `address`, `lat`, `long`, `short_text_address`, `meeting_point_address`, `meeting_point_lat`, `meeting_point_long`, `short_text_meeting_point_address`, `role`, `total_staff_required`, `transport`, `payment_rate`, `short_description`, `description`, `what_you_will_be_doing`, `general_information`, `whatsapp_group_link`, `event_status`, `cron_ongoing_status`, `cron_completed_status`, `status`, `created_at`, `updated_at`) VALUES
(3, 'Testing Tech Expo 2026', 'event-detail-(1).png', NULL, '2026-05-19', '2026-05-20', NULL, NULL, 'Junagadh, Gujarat, India', '21.5128655', '70.4357411', NULL, 'Junagadh, Gujarat, India', '21.5222203', '70.4579436', 'Short Text Meeting Point', 'Waiter', 5, 1, 10.00, 'Join us for a 3-day tech exhibition supporting guest management and coordination.', '<p><span style=\"color: rgb(78, 95, 132); font-family: &quot;DM Sans&quot;; font-size: 16px;\">This is a large-scale outdoor concert. You will be part of the hospitality and bar service team. The event is expected to host over 20,000 attendees.</span></p>', '<ul style=\"padding-left: 2rem; margin-bottom: 0px; padding-inline-start: 20px; color: rgb(33, 37, 41); font-family: system-ui, -apple-system, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, &quot;Liberation Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><li style=\"color: rgb(78, 95, 132); font-family: &quot;DM Sans&quot;;\">Serving drinks</li><li style=\"color: rgb(78, 95, 132); font-family: &quot;DM Sans&quot;;\">Handling payments (card only)</li><li style=\"color: rgb(78, 95, 132); font-family: &quot;DM Sans&quot;;\">Maintaining cleanliness at bar stations</li><li style=\"color: rgb(78, 95, 132); font-family: &quot;DM Sans&quot;;\">Assisting customers</li><li style=\"color: rgb(78, 95, 132); font-family: &quot;DM Sans&quot;;\">Reporting to the area supervisor</li></ul>', '<p><span style=\"color: rgb(78, 95, 132); font-family: &quot;DM Sans&quot;; font-size: 16px;\">Arrive 15 minutes early. Bring valid ID. No late entry will be allowed. Please ensure your phone is fully charged for clock-in and communication.</span></p>', 'WhatsApp Group Link', 1, 1, 1, 1, '2026-05-21 07:01:10', '2026-05-21 07:46:03'),
(4, 'Tech Expo 2026', 'event-detail-(1).png', NULL, '2026-05-17', '2026-05-23', NULL, NULL, 'Junagadh, Gujarat, India', '21.5128652', '70.4357409', NULL, 'Junagadh, Gujarat, India', '21.5222203', '70.4579436', 'Short Text Meeting Point', 'Server', 5, 1, 12.00, 'Join us for a 3-day tech exhibition supporting guest management and coordination.', '<p><span style=\"color: rgb(78, 95, 132); font-family: &quot;DM Sans&quot;; font-size: 16px;\">This is a large-scale outdoor concert. You will be part of the hospitality and bar service team. The event is expected to host over 20,000 attendees.</span></p>', '<ul style=\"padding-left: 2rem; margin-bottom: 0px; padding-inline-start: 20px; color: rgb(33, 37, 41); font-family: system-ui, -apple-system, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, &quot;Liberation Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><li style=\"color: rgb(78, 95, 132); font-family: &quot;DM Sans&quot;;\">Serving drinks</li><li style=\"color: rgb(78, 95, 132); font-family: &quot;DM Sans&quot;;\">Handling payments (card only)</li><li style=\"color: rgb(78, 95, 132); font-family: &quot;DM Sans&quot;;\">Maintaining cleanliness at bar stations</li><li style=\"color: rgb(78, 95, 132); font-family: &quot;DM Sans&quot;;\">Assisting customers</li><li style=\"color: rgb(78, 95, 132); font-family: &quot;DM Sans&quot;;\">Reporting to the area supervisor</li></ul>', '<p><span style=\"color: rgb(78, 95, 132); font-family: &quot;DM Sans&quot;; font-size: 16px;\">Arrive 15 minutes early. Bring valid ID. No late entry will be allowed. Please ensure your phone is fully charged for clock-in and communication.</span></p>', 'WhatsApp Group Link', 1, 1, 1, 1, '2026-05-21 10:15:55', '2026-05-24 00:00:07'),
(5, 'Forbidden Fruit 2026', '1001_1765554440_fest.avif', NULL, '2026-05-27', '2026-05-31', NULL, NULL, 'Royal Hospital Kilmainham, Military Road, Kilmainham, Dublin 8, Irlanda', '53.3432004', '-6.300126199999999', NULL, 'Royal Hospital Kilmainham, Military Road, Kilmainham, Dublin 8, Irlanda', '53.3432004', '-6.300126199999999', 'We\'ll be waiting for you in the main entrance to scan your Qr code and give you your working wristband', 'Bar Staff', 70, 0, 1540.00, 'On the Bank Holiday Weekend May 30th - 31st May, 2026, Forbidden Fruit will return as the first festival of the summer, for what will be a special celebration and back to the summer we know best.', '<p>In the heart of Dublin city, Forbidden Fruit is the capital\'s first and longest-running city-center festival. On the Bank Holiday Weekend May 30th - 31st May, 2026, Forbidden Fruit will return as<span style=\"font-weight:600\" data-token-index=\"1\" class=\"notion-enable-hover\"> the first festival of the summer</span>, for what will be a special celebration and back to the summer we know best</p><!-- notionvc: 0f65a25b-7036-472f-a3b2-636f3dfa0d52 -->', '<ul>\r\n<li>We will all be working as part of the <strong>bar team</strong></li>\r\n<li>Some people will be pouring pints, managing the serving of canned spirits, pouring spirits &amp; mixed drinks, operating the tills or serving customers - lots of options and all a great way to interact with people!</li>\r\n<li>You’ll be told your position on the day. We kindly ask you to follow the instructions to ensure a smooth bar setup. You’ll be working both days in the same position unless changed by the manager.</li>\r\n<li><strong>SMILE! THE MORE YOU SMILE, THE MORE CRAIC YOU WILL HAVE!</strong></li>\r\n</ul>\r\n<!-- notionvc: ea4eefef-cd9f-46fe-814a-72d60587e76b -->', '<ul>\r\n<li>You will receive an email during the week with instructions and a ticket download button (Please check your inbox and spam folder)</li>\r\n<li>You have to complete the induction to receive your QR Code pass (Download it to your phone or add to your wallet to make it easier)</li>\r\n<li>On arrival at the meeting point, we will scan your QR code to check you in and give you your working wristband</li>\r\n<li>IF YOU HAVE NOT COMPLETED THE INDUCTION YOU WILL NOT BE PERMITTED ON THE SITE</li>\r\n</ul><p>Dress Code</p><p>\r\n<!-- notionvc: fd1bb5b5-c5c9-4992-82ea-e4a4eaa21526 --></p><ul>\r\n<li>Warm, <strong>black</strong> clothes</li>\r\n<li>A warm jumper - you will be given a branded t-shirt to wear over your clothes on the day.</li>\r\n<li>Comfortable shoes (black is preferable)</li>\r\n<li>Backpacks must be left at the back of the bar in the designated area</li>\r\n</ul>\r\n<!-- notionvc: def43b51-69f7-432c-82fd-1594ec9752ba -->', 'https://chat.whatsapp.com/GLul3380j8wHtBZ1K8yI8f?mode=gi_t', 1, 1, 1, 1, '2026-05-26 10:43:51', '2026-06-01 00:00:06'),
(6, 'Team JDI Technology', 'Mobile-Application.png', NULL, '2026-06-02', '2026-06-05', NULL, NULL, 'JDI TECHNOLOGY PVT LTD, Zanzarda Road, Vishnu Colony, Junagadh, Gujarat, India', '21.5238467', '70.4349427', NULL, 'JDI TECHNOLOGY PVT LTD, Zanzarda Road, Vishnu Colony, Junagadh, Gujarat, India', '21.5238467', '70.4349427', 'Work', 'Bar,,', 5, 1, 15.40, 'ggg', '<p>gggg</p>', '<p>ggg</p>', '<p>ggg</p>', 'https://chat.whatsapp.com/GLul3380j8wHtBZ1K8yI8f?mode=gi_t', 0, 1, 1, 1, '2026-05-29 13:45:04', '2026-06-06 00:00:05'),
(7, 'teste', '1001_1765554440_fest.avif', NULL, '2026-06-01', '2026-06-01', NULL, NULL, '497 Wyckham Way, Ballinteer, Dublin 16, Irlanda', '53.2841666', '-6.2412926', NULL, '497 Wyckham Way, Ballinteer, Dublin 16, Irlanda', '53.2841666', '-6.2412926', 'fff', 'teste', 23, 1, 15.40, 'sadd', '<p>asdasd</p>', '<p>adsad</p>', '<p>sds</p>', 'sddsfdfs', 1, 1, 1, 1, '2026-06-01 13:36:16', '2026-06-02 00:00:05'),
(8, 'Addison Rae', '8640x640.jpeg', NULL, '2026-06-03', '2026-06-03', NULL, NULL, 'Royal Hospital Kilmainham, Military Road, Kilmainham, Dublin 8, Irlanda', '53.3432004', '-6.300126199999999', NULL, 'Royal Hospital Kilmainham, Military Road, Kilmainham, Dublin 8, Irlanda', '53.3432004', '-6.300126199999999', 'Accreditation Tent', 'Bar Staff', 15, 0, 15.40, 'Global pop sensation Addison Rae will perform a headline show at the Irish Museum of Modern Art, Dublin, on Wednesday 3 June 2026.', '<p><font color=\"#000000\" face=\"Red Hat Display\"><span style=\"font-size: 16px; background-color: rgb(245, 246, 246);\">The show follows a monumental year for Addison, who has rapidly become one of the most recognisable young stars in music and film. Her debut album Addison, released in June, received widespread critical acclaim. The New York Times called it “one of the year’s signature pop releases,” while the Associated Press hailed her arrival as a “new pop powerhouse.”Billboard declared that “Rae’s debut proves her to be one of pop’s current crew.”&nbsp; Addison’s new era launched with the breakout single Diet Pepsi, her first single with Columbia Records. The track marked her debut on the Billboard...</span></font></p>', '<p>\r\n<!-- notionvc: 4b97979b-4d2e-47d8-93fe-4ebb2bef6d3f --></p><ul>\r\n<li>We will all be working as part of the <strong>bar team</strong></li><li>Some people will be pouring pints, managing the serving of canned spirits, pouring spirits &amp; mixed drinks, operating the tills or serving customers - lots of options and all a great way to interact with people!</li>\r\n<li>You’ll be told your position on the day. We kindly ask you to follow the instructions to ensure a smooth bar setup. You’ll be working both days in the same position unless changed by the manager.</li>\r\n<li><strong>SMILE! THE MORE YOU SMILE, THE MORE CRAIC YOU WILL HAVE!</strong></li>\r\n</ul>', '<p>\r\n<!-- notionvc: 43fd7195-a634-4748-995e-d9d3a722d5f0 --></p><p style=\"text-align: left;\"><strong>Payment</strong></p><p style=\"text-align: left;\">Rate of pay: <strong>€15.40</strong> per hour and you will be paid for the number of <strong>hours</strong> of your working shift</p><p style=\"text-align: left;\">Please ensure you complete the check-in form at the end of your shift using the QR code provided by us on the day</p><p style=\"text-align: left;\">Payment will be made by bank transfer with all payments leaving our bank account on 17th June  - meaning payment will land in your bank account on Thursday or Friday depending on your bank account</p><p style=\"text-align: left;\">Please ensure you have completed your profile&nbsp;with your bank details and PPS number</p><p><strong>What to wear</strong></p><p>Warm, <strong>black</strong> clothes</p><p>A warm jumper - you will be given a branded t-shirt to wear over your clothes on the day.</p><p>Comfortable shoes (black is preferable)</p><p>Backpacks must be left at the back of the bar in the designated area</p><p><br></p>', 'https://chat.whatsapp.com/CRdR93TMieaBUh9GPlx4Sl?s=cl&p=i&ilr=0&amv=1', 1, 1, 1, 1, '2026-06-02 12:13:35', '2026-06-04 00:00:06'),
(9, 'Beyond The Pale', '7f99c198-c0e5-4983-8749-6ef08c8e5a06_ARTIST_PAGE_3_2.jpg', NULL, '2026-06-12', '2026-06-14', NULL, NULL, 'Glendalough Estate, Co. Wicklow, Irlanda', '53.0392434', '-6.2656803', NULL, 'Vicar Street, Thomas Street, The Liberties, Dublin 8, Irlanda', '53.34267639999999', '-6.2778366', '- Bus leaves Dublin Saturday 13th June at 8:30am from Vicar Street. 58-59, Thomas St, The Liberties, Dublin 8\r\n- Bus returns to Dublin (Vicar St) on Sunday night / Monday morning at like 01:00am (TBC)', 'Bar Staff', 83, 1, 15.40, 'Three days of Music, Arts and Food in the wild woodlands and stunning surroundings of Glendalough Estate, Co. Wicklow.', '<h3>Shift</h3><p>\r\n\r\n<!-- notionvc: be878684-7c8d-4b22-9b1a-922aaf536257 --></p><ul>\r\n<li>The working shift varies per bar and you will be informed about your shift by Friday</li>\r\n<li>Each shift will be a minimum of 8/10 hours and a degree of flexibility will be required</li>\r\n</ul>', '<h3>What you will be doing</h3><p>\r\n\r\n<!-- notionvc: 1c8d9ac0-c92b-481a-bedb-cad96ca31ddf --></p><ul>\r\n<li>We will all be working as part of the <strong>bar team</strong></li>\r\n<li>Some people will be pouring pints, managing the serving of canned spirits, pouring spirits &amp; mixed drinks, operating the tills or serving customers - lots of options and all a great way to interact with people!</li>\r\n<li><strong>SMILE! THE MORE YOU SMILE, THE MORE CRAIC YOU WILL HAVE!</strong></li>\r\n</ul>', '<h3>Accreditation</h3><p>\r\n\r\n<!-- notionvc: a24cc993-c425-4e30-99c8-1e4ef32784b6 --></p><ul>\r\n<li>You will receive an email from <a href=\"mailto:accreditation@nordevents.ie\">accreditation@nordevents.ie</a> this week with instructions and a ticket download button (Please check your inbox and spam folder)</li>\r\n<li>You have to complete the induction to receive your QR Code pass (Download it to your phone or add to your wallet to make it easier)</li>\r\n<li>On the bus we will scan your QR code to check you in and give you your working wristband</li>\r\n<li>IF YOU HAVE NOT COMPLETED THE INDUCTION YOU WILL NOT BE PERMITTED ON THE SITE</li>\r\n</ul><h3>Accommodation</h3><p>\r\n\r\n<!-- notionvc: 46b34133-7c7f-4ede-b9ec-62a7fdd33eac --></p><ul>\r\n<li><strong>You need to bring your own tent, mattress and sleeping bag</strong></li>\r\n<li>There will be hot showers available in the campsite</li>\r\n</ul><h3>What to wear</h3><p>\r\n\r\n<!-- notionvc: e28af4f7-8c05-4a74-9c34-4651f2b25a4e --></p><ul>\r\n<li>Warm clothes, preferably black, sufficient for 2 days, rain jacket</li>\r\n<li>Comfortable shoes, (black is preferable and bring a spare pair)</li>\r\n<li>You will each be given branded t-shirts</li>\r\n</ul><h3><strong>Food &amp; Break</strong></h3><p>\r\n\r\n<!-- notionvc: dfbd0155-715d-448f-9e0c-1b88399e2daf --></p><ul>\r\n<li>Bring your pre-packed food or there are lots of options available for purchase at the event</li>\r\n<li>We’re staying at a campsite — there’s no fridge or kitchen, so plan accordingly</li>\r\n<li>Bring anything else you think you will need to make your life easier! (Power bank, bottle of water, sunscreen)</li>\r\n<li>Your break time will be scheduled by the bar supervisor during your shift</li>\r\n</ul><h3>Payment</h3><p>\r\n\r\n<!-- notionvc: 9a007ac7-c557-4bc1-ae4e-206b1f4df065 --></p><ul>\r\n<li>Rate of pay: <strong>€15.40</strong> per hour and you will be paid for the number of <strong>hours</strong> of your working shift</li>\r\n<li>Payment will be made by bank transfer with all payments leaving our bank account on June 24th  - meaning payment will land in your bank account on Thursday / Friday depending on your bank</li>\r\n<li>Please ensure you have completed your profile&nbsp;with your bank details.&nbsp;</li>\r\n</ul>', 'https://chat.whatsapp.com/Dr6xKCdOXSsHqGhSFNMPlW?s=cl&p=i&ilr=0&amv=1', 1, 1, 1, 1, '2026-06-04 18:04:38', '2026-06-15 00:00:06'),
(10, 'Teste push', '7f99c198-c0e5-4983-8749-6ef08c8e5a06_ARTIST_PAGE_3_2.jpg', NULL, '2026-06-10', '2026-06-10', NULL, NULL, 'Phoenix Park, Dublin 8, Irlanda', '53.3558823', '-6.3298133', NULL, 'Phoenix Park, Dublin 8, Irlanda', '53.3558823', '-6.3298133', 'Apartment 315, Block F, Core 2', 'Receptionist', 2, 0, 15.40, 'dsdds', '<p>sd</p>', '<p>sd</p>', '<p>sd</p>', 'https://chat.whatsapp.com/GLul3380j8wHtBZ1K8yI8f?mode=gi_t', 1, 1, 1, 1, '2026-06-09 14:21:34', '2026-06-11 00:00:07'),
(11, 'Zach Bryan - Belfast', 'images.jpeg', NULL, '2026-06-17', '2026-06-18', NULL, NULL, 'Boucher Road Playing Fields, Boucher Road, Belfast, Reino Unido', '54.5746028', '-5.969221999999999', NULL, 'Vicar Street, Thomas Street, The Liberties, Dublin 8, Irlanda', '53.34267639999999', '-6.2778366', 'Bus meeting point:\r\n\r\nTransport provided from Dublin and back to Dublin on both days\r\n\r\nReturn Trips\r\n\r\n23 June 2026: Dublin - Belfast\r\nMeeting time: 1:30pm \r\nReturn at: 10:30pm\r\n\r\n24 June 2026: Dublin Belfast\r\nMeeting time: 1:30pm \r\nReturn at: 10:30pm', 'Bar Staff', 80, 1, 15.40, 'Zach Bryan in Belfast - \r\nDaily transport provided from Dublin (return trip) - Availability for both days required', '<p>Zach Bryan will bring his \"With Heaven On Tour\" to Belfast for two massive outdoor concerts at the Boucher Road Playing Fields on Tuesday, June 23, and Wednesday, June 24, 2026, supported by Dijon.</p>', '<p>- We will all be working as part of the bar team</p><p>- Some people will be pouring pints, managing the serving of canned spirits, pouring spirits &amp; mixed drinks, operating the tills or serving customers - lots of options and all a great way to interact with people!</p><p>- SMILE!&nbsp; THE MORE YOU SMILE, THE MORE CRAIC YOU WILL HAVE!</p>', '<p><strong>Check-in/Check-out</strong></p><p><font color=\"#333b3f\">- You need to sign the check-in list as soon as you begin your shift</font></p><p><font color=\"#333b3f\">- You need to scan the Check-out QR code located at the bar (or use the link in the group) every day, shortly after finishing your shift. The link will be shared in the group soon</font></p><p><font color=\"#333b3f\">- Any overtime must be officially approved by the bar manager and recorded through the QR code to be considered</font></p><p><strong>Payment</strong></p><p>- Rate of pay: €15.40 per hour and you will be paid for the number of hours of your working shift</p><p>- Payment will be made by bank transfer with all payments leaving our bank account on July 8th&nbsp; - meaning payment will land in your bank account on Wednesday/Tuesday depending on your bank</p><p><strong>Food &amp; Break</strong></p><p>- Bring your pre-packed food or there are lots of options available for purchase at the event</p><p>- Your break time will be scheduled by the bar supervisor during your shift</p>', 'https://chat.whatsapp.com/FBjqPwVN9Z9AwNAjBePLMz?s=cl&p=i&ilr=0&amv=1', 1, 1, 1, 1, '2026-06-17 11:29:13', '2026-06-19 00:00:06'),
(12, 'Zach Bryan - Cork', 'American-country-music-singer-Zach-Bryan-playing-at-Hyde-Park-in-London-last-year.-Photo-Gus-Stewar', NULL, '2026-06-20', '2026-06-21', NULL, NULL, 'SuperValu Páirc Uí Chaoimh, The Marina, Ballintemple, Corcaigh, Co. Contae Chorcaí, Irlanda', '51.8992051', '-8.4348808', NULL, 'Vicar Street, Thomas Street, The Liberties, Dublin 8, Irlanda', '53.34267639999999', '-6.2778366', 'Meeting time: 11:30am\r\nBus leaves Dublin at: 12noon\r\nBus returns to Dublin at: 10:30pm', 'Bar Staff', 40, 1, 15.40, 'Zach Bryan is coming to Cork for two massive outdoor shows at SuperValu Páirc Uí Chaoimh.', '<p><strong>SHIFT</strong></p><p>- Your shift time will be from 4PM - 10:30PM</p><p>- Gates open at 5:00 PM, with shows starting around 6:00 PM</p><p><br></p><p><strong>PAYMENT</strong></p><p>- Rate of pay: €15.40 per hour and you will be paid for the number of&nbsp; hours of your working shift</p><p>- Please ensure you check-in at the start and at the end of your shift using the form provided by us on the day</p><p>- Payment will be made by bank transfer with all payments leaving our bank account on 1st July&nbsp; - meaning payment will land in your bank account on Thursday or Friday depending on your bank account</p><p>- Please ensure you have completed your profile wi your bank details and PPS number</p>', '<p>- We will all be working as part of the bar team</p><p>- Some people will be pouring pints, managing the serving of canned spirits, pouring spirits, operating the tills or serving customers - lots of options and all a great way to interact with people!</p><p>- SMILE!&nbsp; THE MORE YOU SMILE, THE MORE CRAIC YOU WILL HAVE!</p><p><br></p><p><strong>CHECK-IN/CHECK-OUT</strong></p><p>- You need to sign the check-in list with the bar supervisor as soon as you begin your shift</p><p>- You need to scan the Check-out QR code located at the bar (or use the link in the group) every day, shortly after finishing your shift. The link will be shared in the group soon</p><p>- Any overtime must be officially approved by the bar manager and recorded through the QR code to be considered</p>', '<p><strong>WHAT TO WEAR</strong></p><p><strong>- Black top/jumper, black trousers and black shoes</strong></p><p>- No bags bigger than an A4 page will be allowed entry to the stadium</p><p><br></p><h3><strong>Food &amp; break</strong></h3><p>- Bring your pre-packed food or there are lots of options available for purchase at the event.</p><p>- Your break time will be scheduled by the bar supervisor during your shift.&nbsp;</p><ul>\r\n</ul>', 'https://chat.whatsapp.com/BHKtuQ5KKj32YWrrx9OIKx?s=cl&p=i&ilr=0&amv=1', 1, 1, 1, 1, '2026-06-19 15:42:13', '2026-06-22 00:00:06'),
(13, 'Zach Bryan - Belfast', '5123793_7_org_GettyImages-2159895990_1_.jpg', NULL, '2026-06-23', '2026-06-24', NULL, NULL, 'Boucher Road, Belfast, Reino Unido', '54.5777982', '-5.9627055', NULL, 'Vicar Street, Thomas Street, The Liberties, Dublin 8, Irlanda', '53.34267639999999', '-6.2778366', 'Meeting time: 12:30PM\nBus leaves Dublin at: 1PM \nBus returns to Dublin at: 10:30pm (TBC)', 'Bar Staff', 118, 1, 15.40, 'Zach Bryan brings his tour to Belfast on June 23 for a massive outdoor show at Boucher Playing Fields.', '<p><strong>SHIFT</strong></p><p>- Your shift time will be from 4:00PM - 22:00PM</p><p>- Gates open at 5:00 PM, with shows starting around 6:00 PM</p><p><strong>PAYMENT</strong></p><p>- Rate of pay: €15.40 per hour and you will be paid for the number of&nbsp; hours of your working shift</p><p>- Please ensure you check-in at the start and at the end of your shift using the form provided by us on the day</p><p>- Payment will be made by bank transfer with all payments leaving our bank account on 8th July&nbsp; - meaning payment will land in your bank account on Thursday or Friday depending on your bank account</p><p>- Please ensure you have completed your profile with your bank details and PPS number</p>', '<p><strong>WHAT YOU WILL BE DOING</strong></p><p>- We will all be working as part of the bar team</p><p>- Some people will be pouring pints, managing the serving of canned spirits, pouring spirits, operating the tills or serving customers - lots of options and all a great way to interact with people!</p><p>- SMILE!&nbsp; THE MORE YOU SMILE, THE MORE CRAIC YOU WILL HAVE!</p><p><strong>CHECK-IN/CHECK-OUT</strong></p><p>- You need to sign the check-in list with the bar supervisor as soon as you begin your shift</p><p>- You need to scan the Check-out QR code located at the bar (or use the link in the group) every day, shortly after finishing your shift. The link will be shared in the group soon</p><p>- Any overtime must be officially approved by the bar manager and recorded through the QR code to be considered</p>', '<p><strong>WHAT TO WEAR</strong></p><p>- Black top/jumper, black trousers and black shoes</p><p>- No bags bigger than an A4 page will be allowed entry to the stadium</p><p><strong>FOOD &amp; BREAK</strong></p><p>- Bring your pre-packed food or there are lots of options available for purchase at the event.</p><p>- Your break time will be scheduled by the bar supervisor during your shift.&nbsp;</p>', 'https://chat.whatsapp.com/FBjqPwVN9Z9AwNAjBePLMz?s=cl&p=i&ilr=0&amv=1', 1, 1, 1, 1, '2026-06-19 16:52:40', '2026-07-01 12:50:29'),
(14, 'Kaleidoscope', '14KALEIDOSCOPE+(1).webp', NULL, '2026-07-03', '2026-07-05', NULL, NULL, 'Russborough House & Park, Russborough, Blessington, County Wicklow, Irlanda', '53.14121', '-6.569866999999999', NULL, 'Vicar Street, Thomas Street, The Liberties, Dublin 8, Irlanda', '53.34267639999999', '-6.2778366', '• Bus leaves Dublin on Friday 11:00AM from Vicar Street. 58-59, Thomas St, The Liberties, Dublin 8\r\n• Meeting point: 10:30pm at 58–59 Thomas St, The Liberties, Dublin 8.\r\n• Bus returns to Dublin to the same meeting point (Vicar St) on Sunday night', 'Bar Staff', 47, 1, 15.40, 'Ireland\'s favourite family music camping festival.', '<ul><li>The event is <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">outside Dublin</span>.</li><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">€15.40/hour</span> (this is a <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">registered job)</span>.</li><li>You must be <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">available for all 3 days</span> of the festival.</li><li>We’ll be <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">camping on-site</span> for the weekend, you must bring your <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">own tent, mattress and sleeping bag</span>.</li><li>Shower facilities will be available in the <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">staff camping area</span>.</li></ul>', '<p>\r\n<!-- notionvc: 8ef9995c-aa89-4890-87ee-bf5ab0e46109 --></p><ul>\r\n<li>We will all be working as part of the <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">bar team.</span></li><li>During the event, staff can be assigned to different bar positions, each supporting the service and helping the team run smoothly:<ul><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Tills:</span> Operating the cash register, taking orders, charging customers, and keeping the queue moving smoothly</li><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Server:</span> Serving drinks to customers, keeping the area tidy, and helping with whatever is needed</li><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Pouring:</span> Pouring pints on the tap, ensuring good quality and serving efficiently</li><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">N/P:</span> Managing the serving of canned spirits, keeping stock organised, and ensuring fast service</li><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Runners:</span> Restocking cups, drinks, supporting the bar team, and ensuring nothing runs out</li></ul></li>\r\n</ul>', '<ul><li><p><span data-token-index=\"0\" class=\"notion-enable-hover\" style=\"font-weight: 600;\">Shift information</span></p><ul style=\"margin-bottom: 10px;\"><li>Your shift position will be informed <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">before the event</span>.</li><li>Your shift time will be displayed <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">at the top of this page</span>.</li><li>Follow all instructions from the <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">bar manager and supervisors</span>.</li><li>Stay in your assigned section unless instructed otherwise.</li><li>Keep communication clear and check the group for updates throughout the day.</li><li>And most importantly, <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">have fun! :D</span></li></ul><p><span style=\"font-weight: 600;\">Check-in &amp; check-out<br></span></p><ul style=\"margin-bottom: 10px;\"><li>You must <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">clock in and clock out at the exact time</span> of your assigned shift.</li><li>Any <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">overtime</span> must be <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">approved by the bar manager.</span></li></ul><p><span style=\"font-weight: 600;\">Payment information</span><font color=\"#333b3f\"><span style=\"font-weight: 700;\"></span></font></p><ul style=\"margin-bottom: 10px;\"><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Rate of pay: €15.40 per hour</span>, and you will be paid for the number of hours of your working shift.</li><li>Payment will be processed <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">within two weeks</span> after the event.</li><li>Your <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">IBAN must be Irish</span> (such as AIB, BOI, PTSB, Revolut IE).</li><li>Ensure your bank details are correct to avoid delays.<br></li></ul><p><span style=\"font-weight: 600;\">App requirements<br></span></p><ul style=\"margin-bottom: 10px;\"><li>Register your <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">bank details</span> and <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">PPS number</span> in the <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Profile</span> section of the app.</li><li>This is an <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">availability enquiry only, </span>applying for an event does not confirm your spot.</li><li>After submitting your application, keep an eye on your <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">status</span>. If selected, it will update to “<span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Confirmed”</span>.</li></ul><p><span style=\"font-weight: 600;\">What to wear</span></p><ul style=\"margin-bottom: 10px;\"><li>Black top/jumper, black trousers and black shoes preferred. Choose <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">comfortable</span> clothing.</li><li>The event will probably provide the <span style=\"color: rgb(51, 59, 63); font-weight: 700;\">brand t-shirt.</span></li></ul><p><span style=\"font-weight: 600;\">Food &amp; break<br></span></p><h4></h4><p><span style=\"font-weight: 600;\"></span></p><ul style=\"margin-bottom: 10px;\"><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">You’re entitled to a paid break</span>, scheduled by the bar supervisor. You may use it to rest, eat, drink water or simply recharge before returning to your position.</li><li>Bring your <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">pre-packed food</span>, or you can buy food at the event.</li><li>Please, bring your <span style=\"color: rgb(51, 59, 63); font-weight: 700;\">water bottle.</span> There will be taps with drinking water available for refilling. Let\'s avoid using disposable plastic, <span style=\"color: rgb(51, 59, 63); font-weight: 700;\">help save the planet! :)<br></span></li></ul><p><span data-token-index=\"0\" class=\"notion-enable-hover\" style=\"font-weight: 600;\">Attendance &amp; Conduct</span><font color=\"#333b3f\"><span style=\"font-weight: 700;\"></span></font></p><ul style=\"margin-bottom: 10px;\"><li><span style=\"color: rgb(51, 59, 63); font-weight: 700;\">No-show without justification</span>, or&nbsp; cancellation on the event day, may affect your participation in future events :(</li><li><span style=\"color: rgb(51, 59, 63); font-weight: 700;\"><span style=\"color: rgb(141, 148, 152); font-weight: 400;\">Maintain </span>professional communication</span>, follow instructions from supervisors, and stay in your assigned area unless told otherwise.</li></ul></li></ul>', 'https://chat.whatsapp.com/JI1EijYmRuaIcNgQusks0d', 0, 1, 1, 1, '2026-06-24 06:48:26', '2026-07-06 00:00:05'),
(15, 'Iveagh Gardens/Paddy Power Comedy Festival', '15PPCF_700x700_AIKEN-02e243eb.webp', NULL, '2026-07-02', '2026-07-26', NULL, NULL, 'Iveagh Gardens, Saint Stephen\'s Green, Park, Dublin 2, Irlanda', '53.3351376', '-6.2610343', NULL, 'Clonmel Street, Saint Kevin\'s, Dublin, Irlanda', '53.3360008', '-6.2623237', 'Entrance at Clonmel Street Gate', 'Bar Staff', 20, 0, 15.40, 'An Outdoor Music Series based in the scenic surrounds of Dublin’s ‘Secret Gardens’', '<p data-start=\"0\" data-end=\"82\" class=\"PDq2pG_selectionAnchorContainer\">Please fill in your availability using the link below:</p><p data-start=\"0\" data-end=\"82\" class=\"PDq2pG_selectionAnchorContainer\">\r\n<a data-start=\"57\" data-end=\"82\" rel=\"noopener\" target=\"_new\" class=\"decorated-link\" href=\"https://tally.so/r/RGgWKP\">https://tally.so/r/RGgWKP</a><span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p><p>\r\n</p><p data-start=\"84\" data-end=\"157\" data-is-last-node=\"\" data-is-only-node=\"\">We will send the dates you have been confirmed for in the WhatsApp group.</p><p data-start=\"84\" data-end=\"157\" data-is-last-node=\"\" data-is-only-node=\"\"><br></p>', '<ul><li>We will all be working as part of the <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">bar team</span></li><li>During the event, staff can be assigned to different bar positions, each supporting the service and helping the team run smoothly:<ul><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Tills</span> — Operating the cash register, taking orders, charging customers and keeping the queue moving smoothly</li><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Server</span> — Serving drinks to customers, keeping the area tidy and helping with whatever is needed</li><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Pouring</span> — Pouring pints on the tap, ensuring good quality and serving efficiently</li><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">N/P</span> — Managing the serving of canned spirits, keeping stock organised and ensuring fast service</li><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Runners</span> — Restocking cups, drinks, supporting the bar team and ensuring nothing runs out</li></ul></li><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">SMILE! THE MORE YOU SMILE, THE MORE CRAIC YOU WILL HAVE!</span></li></ul>', '<p><span style=\"font-weight: 600;\">Check-in &amp; check-out<br></span></p><ul><li>You must <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">clock in and clock out at the exact time</span> of your assigned shift.</li><li>Any <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">overtime</span> must be <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">approved by the bar manager.</span></li></ul><p><span style=\"font-weight: 600;\">Payment information</span><font color=\"#333b3f\"><span style=\"font-weight: 700;\"></span></font></p><ul><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Rate of pay: €15.40 per hour</span>, and you will be paid for the number of hours of your working shift.</li><li>Payment will be processed <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">within two weeks</span> after the event.</li><li>Your <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">IBAN must be Irish</span> (such as AIB, BOI, PTSB, Revolut IE).</li><li>Ensure your bank details are correct to avoid delays.<br></li></ul><p><span style=\"font-weight: 600;\">App requirements<br></span></p><ul><li>Register your <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">bank details</span> and <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">PPS number</span> in the <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Profile</span> section of the app.</li><li>This is an <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">availability enquiry only, </span>applying for an event does not confirm your spot.</li><li>After submitting your application, keep an eye on your <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">status</span>. If selected, it will update to “<span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Confirmed”</span>.</li></ul><p><span style=\"font-weight: 600;\">What to wear</span></p><ul><li>Black top/jumper, black trousers and black shoes preferred. Choose <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">comfortable</span> clothing.</li></ul>', 'https://chat.whatsapp.com/IAuoSl20nfRLJRhjZS5Iix?mode=gi_t', 0, 1, 1, 1, '2026-06-25 20:31:14', '2026-07-27 00:00:04'),
(16, 'All Together Now', 'atn24logo.png', NULL, '2026-07-31', '2026-08-02', NULL, NULL, 'Curraghmore Estate, Curraghmore, Portlaw, Co. Waterford, Irlanda', '52.2901761', '-7.35901', NULL, 'Vicar Street, Thomas Street, The Liberties, Dublin 8, Irlanda', '53.34267639999999', '-6.2778366', 'Meeting time: 6:30am (bus leaves Dublin on Friday 7:00AM from Vicar Street. 58-59, Thomas St, The Liberties, Dublin 8). \r\n\r\nBus returns to Dublin (Vicar St) to the same meeting point on Sunday night/early Monday 3:30AM (Sunday to Monday)', 'Bar Staff', 140, 1, 15.40, 'Step into an enchanting weekend of music, art, food, wellness and so much more.', '<ul><li>You must be available for all 3 days of the festival. (There\'s no bus leaving Dublin on Saturday)</li><li>We’ll be camping on-site for the weekend. You have to bring your own tent, mattress and sleeping bag</li><li>You have to bring your own food</li><li>Shower facilities will be available in the staff camping area</li><li>This is a registered job</li></ul><p><span style=\"font-weight: 600;\">What to wear</span></p><ul><li>Black top/jumper, black trousers and black shoes preferred. Choose <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">comfortable</span> clothing.</li><li>You\'ll be given a branded t-shirt on the day.&nbsp;</li></ul><p><strong>Important</strong></p><ul><li>Your application will only be confirmed once you join in the WhatsApp group.</li></ul>', '<ul><li>We will all be working as part of the <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">bar team</span></li><li>During the event, staff can be assigned to different bar positions, each supporting the service and helping the team run smoothly:<ul><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Tills</span> — Operating the cash register, taking orders, charging customers and keeping the queue moving smoothly</li><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Server</span> — Serving drinks to customers, keeping the area tidy and helping with whatever is needed</li><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Pouring</span> — Pouring pints on the tap, ensuring good quality and serving efficiently</li><li><strong>Bartender&nbsp;</strong>—&nbsp;Preparing and serving drinks, taking customer orders, and maintaining high service standards.</li><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">N/P</span> — Managing the serving of canned spirits, keeping stock organised and ensuring fast service</li><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Runners</span> — Restocking cups, drinks, supporting the bar team and ensuring nothing runs out</li></ul></li><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">SMILE! THE MORE YOU SMILE, THE MORE CRAIC YOU WILL HAVE!</span></li></ul>', '<ul><li><p><span data-token-index=\"0\" class=\"notion-enable-hover\" style=\"font-weight: 600;\">Shift information</span></p><ul style=\"margin-bottom: 10px;\"><li>Your shift position will be informed <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">before the event</span>.</li><li>Your shift time will be displayed <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">at the top of this page or it can be informed through the WhatsAppGroup</span></li><li>Follow all instructions from the <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">bar manager and supervisors</span>.</li><li>Stay in your assigned position unless instructed otherwise.</li><li>Keep communication clear and check the group for updates throughout the day.</li><li>And most importantly, <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">have fun! :D</span></li></ul><p><span style=\"font-weight: 600;\">Check-in &amp; check-out<br></span></p><ul style=\"margin-bottom: 10px;\"><li>You must <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">clock in and clock out at the exact time</span> of your assigned shift.</li><li>Any <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">overtime</span> must be <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">approved by the bar manager.</span></li></ul><p><span style=\"font-weight: 600;\">Payment information</span><font color=\"#333b3f\"><span style=\"font-weight: 700;\"></span></font></p><ul style=\"margin-bottom: 10px;\"><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Rate of pay: €15.40 per hour</span>, and you will be paid for the number of hours of your working shift.</li><li>Payment will be processed <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">within two weeks</span> after the event.</li><li>Your <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">IBAN must be Irish</span> (such as AIB, BOI, PTSB, Revolut IE).</li><li>Ensure your bank details are correct to avoid delays.<br></li></ul><p><span style=\"font-weight: 600;\">App requirements<br></span></p><ul style=\"margin-bottom: 10px;\"><li>Register your <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">bank details</span> and <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">PPS number</span> in the <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Profile</span> section of the app.</li><li>This is an <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">availability enquiry only, </span>applying for an event does not confirm your spot.</li><li>After submitting your application, keep an eye on your <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">status</span>. If selected, it will update to “<span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Confirmed”</span>.</li></ul><p><span style=\"font-weight: 600;\">Food &amp; break<br></span></p><h4></h4><p><span style=\"font-weight: 600;\"></span></p><ul style=\"margin-bottom: 10px;\"><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">You’re entitled to a break</span>, scheduled by the bar supervisor. You may use it to rest, eat, drink water or simply recharge before returning to your position.</li><li>Bring your <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">pre-packed food</span>, or you can buy food at the event.</li><li>Please, bring your <span style=\"color: rgb(51, 59, 63); font-weight: 700;\">water bottle.</span> There will be taps with drinking water available for refilling. Let\'s avoid using disposable plastic, <span style=\"color: rgb(51, 59, 63); font-weight: 700;\">help save the planet! :)<br></span></li></ul><p><span data-token-index=\"0\" class=\"notion-enable-hover\" style=\"font-weight: 600;\">Attendance &amp; Conduct</span><font color=\"#333b3f\"><span style=\"font-weight: 700;\"></span></font></p><ul style=\"margin-bottom: 10px;\"><li><span style=\"color: rgb(51, 59, 63); font-weight: 700;\">No-show without justification</span>, or&nbsp; cancellation on the event day, may affect your participation in future events :(</li><li><span style=\"color: rgb(51, 59, 63); font-weight: 700;\"><span style=\"color: rgb(141, 148, 152); font-weight: 400;\">Maintain </span>professional communication</span>, follow instructions from supervisors, and stay in your assigned area unless told otherwise.</li></ul></li></ul>', 'https://chat.whatsapp.com/JxOtmGpnQ1pAsAGcsl9dwL', 0, 1, 1, 1, '2026-06-25 20:44:12', '2026-08-03 00:00:05'),
(18, 'Build & Break', '18Beer_Kegs.webp', NULL, '2026-06-29', '2026-08-08', NULL, NULL, 'Dublin, Irlanda', '53.3498053', '-6.2603097', NULL, 'Dublin, Irlanda', '53.3498053', '-6.2603097', 'TBC at each date', 'Crew', 8, 0, 15.40, 'Build & Break days', '<p data-start=\"52\" data-end=\"151\" class=\"PDq2pG_selectionAnchorContainer\">This space is created for team members to clock in and clock out on event setup and breakdown days.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p><p>\r\n</p><p data-start=\"153\" data-end=\"315\" data-is-last-node=\"\" data-is-only-node=\"\">Please ensure your attendance is recorded correctly at the beginning and end of each shift to keep accurate working hours and support event operations management.</p>', '<p data-start=\"195\" data-end=\"225\" class=\"PDq2pG_selectionAnchorContainer\">Main roles:<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p><p>\r\n</p><ul data-start=\"226\" data-end=\"546\">\r\n<li data-section-id=\"p1rb9t\" data-start=\"226\" data-end=\"267\">\r\nReceiving and checking stock deliveries\r\n</li>\r\n<li data-section-id=\"rj7lwi\" data-start=\"268\" data-end=\"296\">\r\nMoving and organising kegs\r\n</li>\r\n<li data-section-id=\"1rwzkj2\" data-start=\"297\" data-end=\"341\">\r\nOrganising consumables and non-consumables\r\n</li>\r\n<li data-section-id=\"a1xznt\" data-start=\"342\" data-end=\"380\">\r\nPreparing bar equipment and supplies\r\n</li>\r\n<li data-section-id=\"mcrgtw\" data-start=\"381\" data-end=\"427\">\r\nSupporting the setup and layout of bar areas\r\n</li>\r\n<li data-section-id=\"sxz6fs\" data-start=\"428\" data-end=\"476\">\r\nAssisting with general event preparation tasks\r\n</li>\r\n<li data-section-id=\"qpod28\" data-start=\"477\" data-end=\"546\">\r\nCarrying out other duties related to bar setup and event operations</li></ul>', '<p><span style=\"font-weight: 600;\">Check-in &amp; check-out<br></span></p><ul><li>You must <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">clock in and clock out at the exact time</span> of your assigned shift.</li><li>Any <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">overtime</span> must be <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">approved by the crew leader.</span></li></ul><p><span style=\"font-weight: 600;\">Payment information</span><font color=\"#333b3f\"><span style=\"font-weight: 700;\"></span></font></p><ul><li><span style=\"font-weight: 700; color: rgb(51, 59, 63);\">Rate of pay: €15.40 per hour</span>, and you will be paid for the number of hours of your working shift.</li><li>Payment will be processed <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">within two weeks</span> after the event.</li><li>Your <span style=\"font-weight: 700; color: rgb(51, 59, 63);\">IBAN must be Irish</span> (such as AIB, BOI, PTSB, Revolut IE).</li><li>Ensure your bank details are correct to avoid delays.<br></li></ul><p><span style=\"font-weight: 600;\">What to wear</span></p><ul><li>Gloves</li><li>His-vis ves</li><li>Boots</li></ul>', 'https://chat.whatsapp.com/JRh1RjnEKbVJl4JCx0rEzB?mode=gi_t', 0, 1, 1, 1, '2026-06-29 08:29:22', '2026-08-09 00:00:04');
